def check_recovery_slo(snapshot_gb: float, stream_mbps: float, suffix_entries: int = 10000) -> dict:
    if snapshot_gb <= 0 or stream_mbps <= 0:
        raise ValueError('Snapshot size and stream rate must be positive')
    transfer_sec = (snapshot_gb * 8000.0) / stream_mbps
    return {'transfer_sec': round(transfer_sec, 2), 'within_45s_slo': transfer_sec < 40.0}

def jittered_threshold(base_bytes: int, node_id: int) -> int:
    if base_bytes <= 0:
        raise ValueError('base_bytes must be positive')
    offsets = [-0.15, -0.05, 0.0, 0.05, 0.15]
    factor = 1.0 + offsets[node_id % len(offsets)]
    return int(base_bytes * factor)

import zlib

def frame_snapshot_chunk(offset: int, payload: bytes) -> dict:
    if offset < 0:
        raise ValueError('offset must be non-negative')
    crc = zlib.crc32(payload) & 0xFFFFFFFF
    return {'offset': offset, 'size': len(payload), 'crc32c': crc}

def select_reclaimable_segments(segments: list[tuple[str, int]], snap_idx: int, suffix: int = 10000) -> list[str]:
    cutoff = max(0, snap_idx - suffix)
    return [name for name, max_idx in segments if max_idx <= cutoff]

def allocate_peer_chunk_rate(total_budget_mbps: float, active_snapshot_peers: int) -> float:
    if active_snapshot_peers <= 0:
        return 0.0
    return round(total_budget_mbps / min(active_snapshot_peers, 2), 2)

def next_resume_offset(expected_offset: int, incoming_offset: int, chunk_len: int) -> int:
    if incoming_offset != expected_offset:
        raise ValueError(f'Out-of-order chunk: expected {expected_offset}, got {incoming_offset}')
    return expected_offset + chunk_len

def check_compaction_health(wal_bytes: int, byte_thresh: int, failed_snapshots: int) -> str:
    if failed_snapshots > 0:
        return 'PAGE_SNAPSHOT_FAILURE'
    if wal_bytes > byte_thresh * 2:
        return 'WARN_COMPACTION_LAGGING'
    return 'HEALTHY'
